import React from 'react';
import {
  Card,
  CardContent,
  Typography,
  Grid,
  Box,
  Chip,
  LinearProgress
} from '@mui/material';
import { 
  TrendingUp, 
  TrendingDown, 
  AccessTime,
  Warning
} from '@mui/icons-material';

interface FundingStatusProps {
  status: any;
  fundingReturn: any;
  currentFundingRate: number;
}

export const FundingStatus: React.FC<FundingStatusProps> = ({
  status,
  fundingReturn,
  currentFundingRate
}) => {
  const formatPercentage = (value: number) => {
    return `${(value * 100).toFixed(3)}%`;
  };

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('zh-CN', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2
    }).format(value);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'ready': return 'success';
      case 'active': return 'primary';
      case 'extreme': return 'error';
      case 'waiting': return 'default';
      default: return 'default';
    }
  };

  const getStatusIcon = () => {
    switch (status.status) {
      case 'ready':
      case 'active':
        return status.direction === '做多' ? <TrendingUp /> : <TrendingDown />;
      case 'extreme':
        return <Warning />;
      case 'waiting':
        return <AccessTime />;
      default:
        return <AccessTime />;
    }
  };

  return (
    <Card sx={{ mb: 2 }}>
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
          {getStatusIcon()}
          <Typography variant="h6">策略状态</Typography>
          <Chip 
            label={status.message}
            color={getStatusColor(status.status) as any}
          />
        </Box>

        <Grid container spacing={2}>
          <Grid item xs={6}>
            <Typography color="text.secondary">当前费率</Typography>
            <Typography 
              variant="h6" 
              color={currentFundingRate >= 0 ? 'success.main' : 'error.main'}
            >
              {formatPercentage(currentFundingRate)}
            </Typography>
          </Grid>
          <Grid item xs={6}>
            <Typography color="text.secondary">费率水平</Typography>
            <Typography variant="h6">
              {status.fundingLevel}
            </Typography>
          </Grid>
          <Grid item xs={6}>
            <Typography color="text.secondary">交易方向</Typography>
            <Typography variant="h6" color="primary.main">
              {status.direction}
            </Typography>
          </Grid>
          <Grid item xs={6}>
            <Typography color="text.secondary">距离阈值</Typography>
            <Typography variant="h6">
              {formatPercentage(status.distance)}
            </Typography>
          </Grid>

          {/* 收益预期 */}
          <Grid item xs={12}>
            <Typography color="text.secondary" gutterBottom>
              日收益预期
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Typography variant="h6" color="success.main">
                {formatCurrency(fundingReturn.dailyReturn)}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                ({formatPercentage(fundingReturn.returnRate / 1)})
              </Typography>
            </Box>
          </Grid>

          <Grid item xs={12}>
            <Typography color="text.secondary">年化收益率</Typography>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <LinearProgress 
                variant="determinate" 
                value={Math.min(100, fundingReturn.annualizedReturn * 100)}
                sx={{ flexGrow: 1, height: 8, borderRadius: 4 }}
                color="success"
              />
              <Typography variant="body2">
                {formatPercentage(fundingReturn.annualizedReturn)}
              </Typography>
            </Box>
          </Grid>
        </Grid>
      </CardContent>
    </Card>
  );
};
